  "privRetention": "Conservación y eliminación",
  "privRights": "Tus derechos",
  "noticeReopen": "Aviso de almacenamiento",
  "noticeLabel": "Aviso de almacenamiento del navegador",
  "noticeText": "Cook usa el almacenamiento del navegador para las funciones de cocina e inicio de sesión que usas. No se añade almacenamiento publicitario ni analítico.",
  "noticeClose": "Cerrar aviso de almacenamiento",
  "privDraftLabel": "Borrador — actualizado el 28 de octubre de 2026.",
  "privDraft": "Las funciones de cuenta se están probando. Los datos del responsable y de los servicios que aparecen abajo deben completarse antes del lanzamiento público.",
  "privWho1": "Cook está gestionado por [nombre legal y dirección postal del responsable]. Escribe a [correo de privacidad] para consultas y solicitudes sobre privacidad. Estos datos deben completarse antes de abrir el registro.",
  "privWhat1": "Cuando creas una cuenta, usamos tu correo, un identificador de cuenta, los registros de autenticación por contraseña y el estado de verificación para ofrecer y proteger tu cuenta. El proveedor de autenticación trata las contraseñas como hashes seguros; Cook no guarda contraseñas legibles. Guardamos la distribución de tu cocina, el idioma elegido, el tema y las unidades de medida para restaurar tus ajustes en todos tus dispositivos. Para tener una cuenta se necesitan un correo y una contraseña; puedes ver recetas sin cuenta.",
  "privWhat2": "El tratamiento de la cuenta y los ajustes es necesario para prestar el servicio de cuenta que solicitas (artículo 6.1.b del RGPD). Se pueden tratar registros limitados de seguridad y prevención de abusos por interés legítimo (artículo 6.1.f), siempre que sea necesario y tras la debida ponderación. Los correos de verificación y de restablecimiento de contraseña son mensajes de servicio, no publicidad. La función de cuenta no añade publicidad ni analítica.",
  "privStorage1": "Cook usa sessionStorage para llevar tu cocina, el progreso de la receta y tus elecciones entre páginas de la misma pestaña. Si has iniciado sesión, también guarda tu sesión de autenticación. El navegador suele borrarlo al terminar la sesión de la pestaña, pero la restauración de sesiones del navegador puede conservarlo. Al cerrar sesión se borran los datos de la pestaña de Cook. El cierre del aviso de almacenamiento solo se guarda en esa pestaña. Los scripts propios de Cook no crean cookies. Tus proveedores de alojamiento o de servicios pueden realizar tratamientos de seguridad propios que deben documentarse antes del lanzamiento.",
  "privStorage2": "Aceptar y el botón de cerrar del aviso de almacenamiento solo cierran el aviso. No autorizan analítica, publicidad ni ningún otro seguimiento opcional. Cualquier almacenamiento no esencial en el futuro requerirá una elección aparte antes de empezar, con un rechazo y una retirada igual de sencillos.",
  "privOther1": "La función de voz actual de la lista de recetas pide a country.is un país aproximado a partir de tu dirección IP para elegir el idioma de voz. Si usas el reconocimiento por micrófono, tu navegador puede enviar el audio a su proveedor de reconocimiento de voz. También puedes escribir los ingredientes. Estos proveedores, sus políticas y la base jurídica de estas funciones deben revisarse antes del lanzamiento público.",
  "privProviders1": "Proveedor de cuentas previsto: Supabase (PostgreSQL y autenticación gestionados), con una región de base de datos seleccionada en la UE. Proveedor de correo: [proveedor]. Alojamiento web: [proveedor]. El responsable debe confirmar los proveedores reales, los contratos de encargo del tratamiento, los subencargados, la ubicación de los registros y cualquier transferencia fuera del EEE. Una región de base de datos en la UE no excluye por sí sola las transferencias internacionales. Cuando proceda, indica la decisión de adecuación o las garantías contractuales aplicables y cómo obtener una copia.",
  "privRetention1": "Los ajustes de la cuenta se conservan mientras tu cuenta esté activa. Puedes solicitar la eliminación a través del contacto de privacidad indicado arriba. Antes del lanzamiento, el responsable debe especificar el procedimiento de respuesta a las solicitudes de eliminación, la caducidad de las cuentas no verificadas y los plazos de conservación de los registros de seguridad y de las copias de seguridad. Los datos eliminados pueden permanecer en copias de seguridad de acceso restringido hasta que termine el plazo de conservación documentado.",
  "privRights1": "Según las condiciones aplicables, puedes solicitar el acceso, la rectificación, la supresión, la limitación o la portabilidad, u oponerte al tratamiento basado en el interés legítimo. Contacta con el responsable indicado arriba; las solicitudes suelen responderse en un mes y se explicará cualquier prórroga legal. Puedes presentar una reclamación ante tu autoridad de control, incluida la NAIH de Hungría en naih.hu. Cook no usa los ajustes de la cuenta para decisiones automatizadas con efectos jurídicos o efectos igualmente significativos.",
